import json
import time
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)


def parse_wait(headers, body):
    vals = []
    if headers is not None:
        for key in ('Retry-After', 'X-Retry-In', 'X-RateLimit-Reset'):
            val = headers.get(key)
            if val:
                try:
                    vals.append(float(val))
                except ValueError:
                    pass
    if body:
        try:
            data = json.loads(body)
            if isinstance(data, dict):
                for key in ('retry_after', 'retryAfter', 'wait', 'wait_seconds', 'retry_in', 'delay'):
                    val = data.get(key)
                    if isinstance(val, (int, float)):
                        vals.append(float(val))
                    elif isinstance(val, str):
                        try:
                            vals.append(float(val))
                        except ValueError:
                            pass
        except Exception:
            pass
    return max(vals) if vals else None

class Client:
    def __init__(self):
        self.token = None
        self.refreshes = 0
        self.calls = 0

    def get_token(self):
        req = urllib.request.Request(BASE + '/token', method='POST')
        while True:
            try:
                with urllib.request.urlopen(req, timeout=30) as resp:
                    data = json.load(resp)
                    self.token = data['token']
                    self.refreshes += 1
                    return
            except urllib.error.HTTPError as e:
                body = e.read().decode('utf-8', 'replace')
                wait = parse_wait(e.headers, body)
                if e.code == 429 or 500 <= e.code < 600:
                    time.sleep(wait if wait is not None else 2)
                    continue
                raise RuntimeError(f'token request failed {e.code}: {body}')
            except (urllib.error.URLError, TimeoutError) as e:
                time.sleep(2)

    def get(self, path):
        if self.token is None:
            self.get_token()
        backoff = 1.0
        refreshed = False
        while True:
            self.calls += 1
            req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + self.token})
            try:
                with urllib.request.urlopen(req, timeout=30) as resp:
                    return json.load(resp)
            except urllib.error.HTTPError as e:
                body = e.read().decode('utf-8', 'replace')
                if e.code == 401 and not refreshed:
                    self.get_token()
                    refreshed = True
                    continue
                if e.code == 429 or 500 <= e.code < 600:
                    wait = parse_wait(e.headers, body)
                    time.sleep(wait if wait is not None else backoff)
                    backoff = min(backoff * 2, 30.0)
                    continue
                if e.code == 401:
                    self.get_token()
                    refreshed = False
                    continue
                raise RuntimeError(f'GET {path} failed {e.code}: {body}')
            except (urllib.error.URLError, TimeoutError):
                time.sleep(backoff)
                backoff = min(backoff * 2, 30.0)


def parse_utc(value):
    text = value[:-1] + '+00:00' if value.endswith('Z') else value
    dt = datetime.fromisoformat(text)
    if dt.tzinfo is None:
        raise ValueError(f'naive timestamp: {value}')
    return dt.astimezone(timezone.utc)

client = Client()
seen = set()
duplicates_skipped = 0
qualifying = []
page_path = '/orders?page=1'
page_count = 0

while page_path:
    page = client.get(page_path)
    page_count += 1
    items = page.get('items')
    if not isinstance(items, list):
        raise RuntimeError(f'page {page_count} missing items')
    for order in items:
        oid = order['id']
        if oid in seen:
            duplicates_skipped += 1
            continue
        seen.add(oid)
        placed = parse_utc(order['placed_at'])
        if placed >= START and placed < END and order['status'] == 'shipped':
            qualifying.append(order)
    page_path = page.get('next')
    if page_path and not isinstance(page_path, str):
        raise RuntimeError(f'invalid next link: {page_path"'!r}'"')
    print(f'processed page {page_count}; unique orders {len(seen)}; qualifying {len(qualifying)}', flush=True)

customer_cache = {}
by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for idx, order in enumerate(qualifying, 1):
    cid = order['customer_id']
    if cid not in customer_cache:
        customer_cache[cid] = client.get('/customers/' + urllib.parse.quote(str(cid), safe=''))
    customer = customer_cache[cid]
    pct = customer['discount_pct']
    discounted = (Decimal(order['amount_cents']) * Decimal(100 - pct) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    cents = int(discounted)
    region = customer['region']
    if region not in by_region:
        raise RuntimeError(f'unknown region {region"'!r}'"')
    by_region[region] += cents
    if idx % 100 == 0:
        print(f'priced {idx}/{len(qualifying)} qualifying orders; cached customers {len(customer_cache)}', flush=True)

total = sum(by_region.values())
result = {
    'total_cents': total,
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates_skipped,
    'by_region': by_region,
}
print(json.dumps({'result': result, 'pages': page_count, 'unique_listings': len(seen), 'customer_cache_size': len(customer_cache), 'token_fetches': client.refreshes, 'requests': client.calls}, sort_keys=True))
PY"

